<?php

namespace App\Service\Search;

use App\Component\Exceptions\MetadataException;
use Exception;
use SolrClientException;
use SolrServerException;
use SolrUpdateResponse;

class SolrRemove extends SolrSearch implements SearchInterface
{

    public function find(): array
    {
        // TODO: Change the autogenerated stub
        throw new Exception("Not yet implemented for SolrRemove");
    }

    public function countLocked($user, array $searchParams, array $lockedIds)
    {
        if (count($lockedIds) === 0) {
            return 0;
        }
        $this->resetQuery();
        $searchParams["page"] = 1;
        PrepareSearch::setFilter($this, $searchParams, $user);
        $filter = ["in" => ["uuid" => $lockedIds]];
        $expression = JsonFilterReader::read($filter, new SolrExprHandler())->getExpression();
        $this->query->addFilterQuery($expression);

        $this->prepareQuery();
        $this->query->addField("uuid");
        $f = $this->query->getFilterQueries();
        try {
            $response = $this->setPage(1)->setHits(0)->doRequest();
            return isset($response->response->numFound) ? $response->response->numFound : 0;
        } catch (SolrServerException|MetadataException $e) {
        }
        return 0;
    }

    public function countNotSeries($user, array $searchParams, array $seriesIds)
    {
        $this->resetQuery();
        if (isset($searchParams["hierarchyLevel"]["series"])) {
            unset($searchParams["hierarchyLevel"]["series"]);
            if (count($searchParams["hierarchyLevel"]) === 0) {
                return 0;
            }
        }
        $searchParams["page"] = 1;
        PrepareSearch::setFilter($this, $searchParams, $user);
        if (count($seriesIds) > 0) {
            $filter = [
                "not" => [
                    ["in" => ["parent" => $seriesIds]]
                ]
            ];
            $expression = JsonFilterReader::read($filter, new SolrExprHandler())->getExpression();
            $this->query->addFilterQuery($expression);
        }

        $this->prepareQuery();
        $this->query->addField("uuid");
        $f = $this->query->getFilterQueries();
        try {
            $response = $this->setPage(1)->setHits(0)->doRequest();
            return $response->response->numFound ?? 0;
        } catch (SolrServerException|MetadataException $e) {
        }
        return 0;
    }

    public function countTilesForSeries(array $seriesIds, $user)
    {
        $this->resetQuery();
        $searchParams = [
            "hierarchyLevel" => ['tile' => "true"],
            "page" => 1
        ];
        PrepareSearch::setFilter($this, $searchParams, $user);
        $filter = ["in" => ["parent" => $seriesIds]];
        $expression = JsonFilterReader::read($filter, new SolrExprHandler())->getExpression();
        $this->query->addFilterQuery($expression);
        $this->prepareQuery();
        $this->query->addField("uuid");
        $f = $this->query->getFilterQueries();
        try {
            $response = $this->setPage(1)->setHits(0)->doRequest();
            return $response->response->numFound ?? 0;
        } catch (SolrServerException|MetadataException $e) {
        }
        return 0;
    }

    /**
     * @throws MetadataException
     */
    public function findSeries($user, array $searchParams, $page, $hits): array
    {
        $this->resetQuery();
        unset($searchParams["hierarchyLevel"]);
        $searchParams["hierarchyLevel"] = ["series" => "true"];
        $searchParams["page"] = $page;
        PrepareSearch::setFilter($this, $searchParams, $user);
        PrepareSearch::setPagination($this, $searchParams, $hits);
        $this->prepareQuery();
        $this->query->addField("uuid");
//        $f = $this->query->getFilterQueries();
        $response = $this->doRequest();
        $numFound = $response->response->numFound ?? 0;
        $docs = $response->response->docs ?? [];
        $ids = array_map(function ($doc) {
            return $doc->uuid;
        }, $docs);
        return [
            "count" => $numFound,
            "ids" => $ids
        ];
    }

    /**
     * @throws MetadataException
     */
    public function findNotSeries($user, array $searchParams, $page, $hits): array
    {
        $this->resetQuery();
        if (isset($searchParams["hierarchyLevel"]["series"])) {
            unset($searchParams["hierarchyLevel"]["series"]);
            if (count($searchParams["hierarchyLevel"]) === 0) {
                return [
                    "count" => 0,
                    "ids" => []
                ];
            }
        }
        $searchParams["page"] = $page;
        PrepareSearch::setFilter($this, $searchParams, $user);
        PrepareSearch::setPagination($this, $searchParams, $hits);
        $this->prepareQuery();
        $this->query->addField("uuid");
        $this->query->addField("parent");
//        $f = $this->query->getFilterQueries();
        $response = $this->doRequest();
        $numFound = $response->response->numFound ?? 0;
        $docs = $response->response->docs ?? [];
        $ids = [];
        $series = [];
        foreach ($docs as $doc) {
            $ids[] = $doc->uuid;
            if ($doc->parent) {
                $series[] = $doc->parent;
            }
        }
        return [
            "count" => $numFound,
            "ids" => $ids,
            "series" => array_unique($series)
        ];
    }

    /**
     * @throws SolrClientException
     * @throws SolrServerException
     */
    public function removeForIds(array $ids, $source): bool
    {
        $this->resetQuery();
        $filter = [
            "and" => [
                ["in" => ["uuid" => $ids]],
                ["eq" => ["source" => $source]]
            ]
        ];
        $expression = JsonFilterReader::read($filter, new SolrExprHandler())->getExpression();
        $this->solr->client->deleteByQuery($expression);
        $response = $this->solr->client->commit();
        return $response->success();
    }

    /**
     * @throws SolrClientException
     * @throws SolrServerException
     */
    public function removeSeries(array $ids, $source): bool
    {
        if (!$this->removeTiles($ids)) {
            return false;
        }
        return $this->removeForIds($ids, $source);
    }

    /**
     * @throws SolrClientException
     * @throws SolrServerException
     */
    private function removeTiles(array $seriesIds): bool
    {
        $this->resetQuery();
        $filter = $this->filterForTiles($seriesIds);
        $expression = JsonFilterReader::read($filter, new SolrExprHandler())->getExpression();
        $this->solr->client->deleteByQuery($expression);
        $response = $this->solr->client->commit();
        return $response->success();
    }

    private function filterForTiles(array $seriesIds): array
    {
        return [
            "and" => [
                ["in" => ["parent" => $seriesIds]],
                ["eq" => ["hierarchyLevel" => 'tile']]
            ]
        ];
    }
}
